					sizeof(_reserved),
					&_reserved);
		if (!rp) {
			par->hotdrop = true;
			return false;
		}

		ret = (*rp == 0);
	}

	if (!(rtinfo->flags & IP6T_RT_FST)) {
		return ret;
	} else if (rtinfo->flags & IP6T_RT_FST_NSTRICT) {
		if (rtinfo->addrnr > (unsigned int)((hdrlen - 8) / 16)) {
			return false;
		} else {
